    float value=lum(ink);
    vec2 relief=vec2(lum(CCSampleWithAlphaSeparated(cc_spriteTexture,uv+vec2(stepUV.x,0.)).rgb),
                     lum(CCSampleWithAlphaSeparated(cc_spriteTexture,uv+vec2(0.,stepUV.y)).rgb))-value;
    float edge=smoothstep(.014,.16,length(relief));
    float d=p.x+.20*(p.y-.5)-(.50+.52*turn.x+.22*turn.y);
    float soft=beam(d,.26),crest=beam(d+.035,.085);
    if(finish<.5){
        float metal=smoothstep(.16,.65,value)*smoothstep(-.025,.16,ink.r-ink.b);
        return ink+tilt*metal*vec3(1.,.83,.59)*(.040*soft+(.080+.16*edge)*crest);
    }
    if(finish<1.5){
        float gold=smoothstep(.28,.68,value)*smoothstep(.5,.78,ink.g/max(.04,ink.r));
        float lacquer=smoothstep(.10,.49,ink.r-ink.g);
        return ink+tilt*(gold*vec3(1.,.82,.55)*(.065*soft+(.10+.12*edge)*crest)
                        +lacquer*vec3(1.,.72,.65)*.045*soft);
    }
    if(finish>3.5){
        float bevel=edge*smoothstep(.21,.66,value)*smoothstep(.06,.28,ink.r-ink.b);
        float inkGloss=(1.-smoothstep(.13,.39,value))*.029;
        return ink+(1.-ink)*tilt*(vec3(1.,.92,.80)*(.009+inkGloss)*soft
                             +vec3(1.,.83,.55)*bevel*(.09*soft+.62*crest));
    }
    if(finish>2.5){
        float pigment=1.-smoothstep(.22,.74,value);
        float cool=smoothstep(-.12,.08,ink.b-ink.r);
        return ink+tilt*edge*pigment*vec3(.73,.79,.84)*(.032*soft+.14*cool*crest);
    }
    float silver=smoothstep(.28,.76,value)*edge;
    return ink+tilt*silver*vec3(.81,.91,1.)*(.075*soft+.22*crest);
