        float body=beam(water,.145);
        float edge=beam(water+.072,.022)+.42*beam(water-.035,.016);
        float refraction=beam(length(normal-lamp*1.32+relief*.30-vec2(-.13,.21)),.29);
        vec3 enamel=ink.rgb*(.75+.21*crest)
                  +vec3(.12,.72,.53)*body*(.34+.25*facets.b)
                  +vec3(.77,.99,.88)*edge*(.34+.35*crest)
                  +vec3(.58,.93,.91)*refraction*(.50+.43*body);
        result=mix(result,enamel,metal);
    }else if(finish<2.5){
        vec3 chips=grain(p*vec2(1.65,2.27)),fine=grain(p*vec2(4.62,6.45)+vec2(.21,.38));
        vec2 n=chips.rg*2.-1.,small=fine.rg*2.-1.;
        float mica=beam(length(n+relief*.38-lamp*1.25-vec2(.18,-.12)),.261);
        float glint=beam(length(small-lamp*1.3-vec2(-.10,.16)),.149);
        float opal=.5+.5*sin(5.6*n.x+2.3*n.y-4.3*lamp.x);
        vec3 silver=mix(vec3(.51,.77,.86),vec3(.76,.65,.86),opal);
        float roll=clamp(.51+.30*n.x+.19*lamp.y,0.,1.);
        vec3 steel=ink.rgb*(.60+.15*roll+.16*chips.b)
                  +silver*(.073+.13*roll+.20*broad+.12*rim+.09*crest);
        steel+=vec3(.84,.95,1.)*mica*(.73+.3*broad)+vec3(.90,.95,1.)*glint*(.48+.46*broad);
        result=mix(result,steel,metal);
    }else{
        vec3 shell=grain(p*vec2(1.15,1.62));
        vec2 normal=shell.rg*2.-1.;
        float facet=beam(length(normal-lamp*1.28+relief*.32-vec2(.10,-.21)),.35);
        float phase=crosscut+.18*normal.x-.11*normal.y+.30*relief.y;
        float reflected=beam(phase,.105);
        float layers=.5+.5*sin(108.*dot(p,normalize(normal+vec2(.001)))+shell.b*6.5);
        vec3 pearl=.79+.17*cos(6.28318*(vec3(.04,.72,.53)+.48*shell.g+.32*dot(normal,lamp)+.07*layers));
        float edge=beam(phase-.073,.032);
        vec3 inlay=ink.rgb*(.71+.22*crest+.08*shell.b)
                 +pearl*(reflected*(.24+.33*layers)+facet*(.47+.34*shell.b))
                 +vec3(.94,.96,1.)*edge*(.31+.32*crest);
        result=mix(result,inlay,metal);
    }
    if(inspection>.5){
        vec2 q=(p-vec2(.47,.44))*vec2(1.,1.4167);
        vec2 r=q+vec2(1.15*turn.x+.11*turn.y,1.13*turn.y-.12*turn.x);
        float across=dot(r,vec2(.885,-.465))+.20;
        float along=dot(r,vec2(.465,.885))+.09;
        float roll=beam(across+dot(relief,vec2(.30,-.19)),.23)*beam(along,.86);
        float cut=beam(across-.13+relief.y*.26,.055)*beam(along,.68);
        float rimLight=beam(dot(r,vec2(.94,.342))-.37+relief.x*.31,.092)*beam(r.y-.12,.72);
        float kicker=beam(abs(dot(r,vec2(.96,.28)))-.93+relief.y*.21,.145)*beam(r.y,1.38)
                     *smoothstep(.26,.84,length(turn));
        vec3 keyColor=finish>2.5?vec3(.95,.84,1.):finish>1.5?vec3(.75,.88,1.):finish>.5?vec3(.75,.98,.84):vec3(1.,.75,.45);
        vec3 polished=result*(.64+.29*roll+.15*crest)
                +keyColor*(.15*roll+.44*cut+.29*kicker)+vec3(.87,.91,.94)*(.19*rimLight+.075*kicker);
        result=mix(result,polished,metal);
    }
    return vec4(result,ink.a)*tint;
}
